import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { isSlug } from "./util.js";

// Runtime-independent style atlas. The JSON is a committed, attributed snapshot
// generated by scripts/import-style-atlas.mjs; the plugin never reads the
// research checkout or depends on dsh-ui-ux-pro-max at runtime.
const DATA_PATH = join(dirname(fileURLToPath(import.meta.url)), "..", "data", "style-atlas.json");
const ATLAS = JSON.parse(readFileSync(DATA_PATH, "utf8"));
const CUSTOM_DIR = "_studio/styles";
const ATTRIBUTION = {
  project: "dsh-ui-ux-pro-max",
  owner: "ChenYiming-aaa",
  repository: "https://github.com/ChenYiming-aaa/dsh-ui-ux-pro-max",
  upstream: "https://github.com/nextlevelbuilder/ui-ux-pro-max-skill",
  license: "MIT",
};

const FONT_STACKS = {
  sans: '"Avenir Next", "Segoe UI", system-ui, -apple-system, sans-serif',
  serif: '"Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif',
  mono: 'ui-monospace, "SF Mono", Menlo, Consolas, monospace',
};

function luminance(color) {
  const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(color || "").trim());
  if (!m) return 0.5;
  let hex = m[1];
  if (hex.length === 3) hex = hex.split("").map((c) => c + c).join("");
  const r = parseInt(hex.slice(0, 2), 16) / 255;
  const g = parseInt(hex.slice(2, 4), 16) / 255;
  const b = parseInt(hex.slice(4, 6), 16) / 255;
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

function fontStack(style, fontMode) {
  const key = fontMode && fontMode !== "auto" ? fontMode : style.theme && style.theme.font;
  return FONT_STACKS[key] || FONT_STACKS.sans;
}

export function styleVars(style, fontMode) {
  const t = style.theme || {};
  const dark = luminance(t.bg) < 0.42;
  const radius = Number.isFinite(Number(t.radius)) ? Number(t.radius) : 12;
  const bodyFont = fontStack(style, fontMode);
  return {
    "--bg": t.bg,
    "--bg-deep": t.surface2 || t.surface || t.bg,
    "--bg-glow": t.surface || t.bg,
    "--panel": t.surface || t.bg,
    "--panel-2": t.surface2 || t.surface || t.bg,
    "--panel-3": t.surface2 || t.surface || t.bg,
    "--panel2": t.surface2 || t.surface || t.bg,
    "--ink": t.text,
    "--ink-soft": t.muted || t.text,
    "--ink-faint": t.muted || t.text,
    "--text": t.text,
    "--muted": t.muted || t.text,
    "--line": t.border || t.muted,
    "--line-strong": t.border || t.text,
    "--border": t.border || t.muted,
    "--gold": t.accent,
    "--gold-soft": t.accent2 || t.accent,
    "--gold-deep": t.accent,
    "--accent": t.accent,
    "--info": t.accent2 || t.accent,
    "--clay": t.accent2 || t.accent,
    "--clay-deep": t.accent,
    "--teal": t.accent2 || t.accent,
    "--teal-deep": t.accent,
    "--ok": dark ? "#7fb08a" : "#4f7d5a",
    "--warn": dark ? "#e0b45d" : "#a6781c",
    "--err": dark ? "#e07a72" : "#a33f38",
    "--radius-card": radius + 8 + "px",
    "--radius-panel": radius + "px",
    "--radius-board": Math.max(2, radius - 2) + "px",
    "--radius-pill": "999px",
    "--radius": radius + "px",
    "--space": "16px",
    "--font-body": bodyFont,
    "--font-display": bodyFont,
    "--font-mono": FONT_STACKS.mono,
  };
}

function publicStyle(style, fontMode) {
  return {
    id: style.id,
    no: style.no,
    name: style.name,
    zh: style.zh,
    tag: style.tag,
    description: style.description,
    category: style.category,
    status: style.status,
    complexity: style.complexity,
    era: style.era,
    keywords: style.keywords,
    primary: style.primary,
    secondary: style.secondary,
    bestFor: style.bestFor,
    avoid: style.avoid,
    light: style.light,
    dark: style.dark,
    performance: style.performance,
    accessibility: style.accessibility,
    prompt: style.prompt,
    checklist: style.checklist,
    theme: style.theme,
    vars: styleVars(style, fontMode),
    source: "built-in",
  };
}

function parseVars(css) {
  const vars = {};
  const re = /(--[a-z0-9-]+)\s*:\s*([^;]+);/gi;
  let m;
  while ((m = re.exec(String(css || "")))) vars[m[1]] = m[2].trim();
  return vars;
}

function slugifyStyle(name) {
  const base = String(name || "style")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  return base || "style";
}

export function createStyles({ fs, rootPath, resolveSystem, readJson, writeJson, removePaths, bumpDesignStamp }) {
  const builtins = new Map(ATLAS.styles.map((style) => [style.id, style]));

  async function listCustom() {
    const root = await fs.resolve(CUSTOM_DIR, { cwd: await rootPath() });
    if (!(await fs.stat(root))) return [];
    const out = [];
    for (const entry of await fs.listDir(root)) {
      if (entry.type !== "file" || !entry.name.endsWith(".json")) continue;
      try {
        const data = await readJson(CUSTOM_DIR + "/" + entry.name);
        if (!data || !data.id || !data.tokenCss) continue;
        out.push({
          id: data.id,
          name: data.name,
          description: data.description || "",
          createdAt: data.createdAt || null,
          theme: data.theme || null,
          vars: data.vars || parseVars(data.tokenCss),
          source: "custom",
        });
      } catch (_) {}
    }
    return out.sort((a, b) => (a.name < b.name ? -1 : 1));
  }

  async function list(fontMode) {
    return {
      count: ATLAS.styles.length,
      builtinCount: ATLAS.styles.length,
      attribution: ATTRIBUTION,
      styles: ATLAS.styles.map((style) => publicStyle(style, fontMode)).concat(await listCustom()),
    };
  }

  async function get(styleId) {
    if (builtins.has(styleId)) return publicStyle(builtins.get(styleId));
    const custom = (await listCustom()).find((s) => s.id === styleId);
    if (custom) return custom;
    throw new Error("unknown style: " + styleId);
  }

  async function apply(slug, styleId, options) {
    if (!isSlug(slug)) throw new Error("invalid slug");
    const fontMode = options && options.fontMode ? String(options.fontMode) : "auto";
    const tokenRel = options && options.tokenRel ? String(options.tokenRel) : "css/token.css";
    const builtin = builtins.get(styleId);
    let css;
    let name;
    let preserved = 0;
    if (builtin) {
      const sys = await resolveSystem(slug);
      if (!(await fs.stat(sys))) throw new Error("unknown design system: " + slug);
      const target = await fs.resolve(tokenRel, { cwd: fs.processPath(sys) });
      let oldCss = "";
      try { oldCss = await fs.readText(target); } catch (_) {}
      const vars = styleVars(builtin, fontMode);
      const core = new Set(vars && Object.keys(vars));
      const oldVars = parseVars(oldCss);
      const extra = Object.keys(oldVars).filter((key) => !core.has(key));
      preserved = extra.length;
      const lines = [
        "/* ============================================================",
        "   " + builtin.name + " — " + (builtin.zh || ""),
        "   Adapted from dsh-ui-ux-pro-max (MIT).",
        "   Style ID: " + builtin.id,
        "   ============================================================ */",
        "",
        ":root {",
        "  color-scheme: " + (luminance(builtin.theme.bg) < 0.42 ? "dark" : "light") + ";",
      ];
      for (const key of Object.keys(vars)) lines.push("  " + key + ": " + vars[key] + ";");
      lines.push("}");
      if (extra.length) {
        lines.push("", "/* Preserved design-specific tokens */", ":root {");
        for (const key of extra) lines.push("  " + key + ": " + oldVars[key] + ";");
        lines.push("}");
      }
      css = lines.join("\n") + "\n";
      await fs.writeText(target, css);
      name = builtin.name;
    } else {
      const custom = (await listCustom()).find((s) => s.id === styleId);
      if (!custom) throw new Error("unknown style: " + styleId);
      const sys = await resolveSystem(slug);
      if (!(await fs.stat(sys))) throw new Error("unknown design system: " + slug);
      const target = await fs.resolve(tokenRel, { cwd: fs.processPath(sys) });
      css = custom.tokenCss;
      await fs.writeText(target, css);
      name = custom.name;
    }
    await bumpDesignStamp(slug).catch(function () {});
    return { applied: styleId, name, tokenCss: tokenRel, preserved };
  }

  async function save(slug, name, description) {
    if (!isSlug(slug)) throw new Error("invalid slug");
    const sys = await resolveSystem(slug);
    if (!(await fs.stat(sys))) throw new Error("unknown design system: " + slug);
    const target = await fs.resolve("css/token.css", { cwd: fs.processPath(sys) });
    const tokenCss = await fs.readText(target);
    const vars = parseVars(tokenCss);
    let id = slugifyStyle(name);
    const existing = new Set((await listCustom()).map((s) => s.id));
    while (builtins.has(id) || existing.has(id)) id = id + "-2";
    const style = {
      id,
      name: String(name || id).trim().slice(0, 80),
      description: String(description || "").trim().slice(0, 300),
      createdAt: new Date().toISOString(),
      tokenCss,
      vars,
    };
    await writeJson(CUSTOM_DIR + "/" + id + ".json", style);
    return { style: { id, name: style.name, description: style.description, createdAt: style.createdAt, vars, source: "custom" }, tokenCss: "css/token.css" };
  }

  async function remove(styleId) {
    if (!isSlug(styleId)) throw new Error("invalid style id");
    const target = await fs.resolve(CUSTOM_DIR + "/" + styleId + ".json", { cwd: await rootPath() });
    if (!(await fs.stat(target))) throw new Error("unknown custom style: " + styleId);
    await removePaths([fs.processPath(target)], await rootPath());
    return { removed: styleId };
  }

  return { list, get, apply, save, remove, styleVars, parseVars };
}
